# Result codes
_TB_WIN = 1; _TB_LOSS = 2; _TB_DRAW = 3
_TB_TYPE_MAP = {"queen":2,"right":3,"knight":4,"bishop":5,"pawn":6}

# Decompress on module load
_ENDGAME_TB = {}
def _init_endgame_tb():
    global _ENDGAME_TB
    try:
        raw = _zlib.decompress(_b64.b64decode(_TB_DATA))
        _ENDGAME_TB = _pkl.loads(raw)
    except Exception:
        _ENDGAME_TB = {}
_init_endgame_tb()

def _probe_endgame_tb(board, _pn_func):
    """Probe endgame tablebase. Returns (hit, score_for_stm)."""
    pcs = []
    for p in board.get_pieces():
        pcs.append(p)
        if len(pcs) > 4: return False, 0
    n = len(pcs)
    if n < 2: return False, 0
    if n == 2: return True, 0  # K vs K = draw
    wk = bk = -1
    extra = []
    for p in pcs:
        nm = _pn_func(p)
        sq = p.position.y * 5 + p.position.x
        if nm == "king":
            if p.player.name == "white": wk = sq
            else: bk = sq
        else:
            pt = _TB_TYPE_MAP.get(nm, 0)
            pc = 0 if p.player.name == "white" else 1
            extra.append((pt, pc, sq))
    if wk < 0 or bk < 0: return False, 0
    extra.sort()
    mk = tuple((t,c) for t,c,s in extra)
    if mk not in _ENDGAME_TB: return False, 0
    tbl = _ENDGAME_TB[mk]
    stm = 0 if board.current_player.name == "white" else 1
    ne = len(extra)
    if ne == 1:
        idx = wk*1250 + bk*50 + extra[0][2]*2 + stm
    elif ne == 2:
        idx = wk*31250 + bk*1250 + extra[0][2]*50 + extra[1][2]*2 + stm
    else: return False, 0
    if idx >= len(tbl): return False, 0
    r = tbl[idx]
    if r == _TB_WIN:  return True,  95000
    if r == _TB_LOSS: return True, -95000
    if r == _TB_DRAW: return True,  0
    return False, 0
